import {pedagogiTopics, selectPedagogiQuestions, pedagogiTryoutMinutes} from './pedagogi.js';

export function pedagogiPage(topicId, {bank, shell, title, btn, icon, esc, sourceLinks}) {
  const topic=topicId?pedagogiTopics.find(t=>t.id===topicId):null;
  const list=items=>`<ul>${items.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
  if(topicId&&!topic)return shell(`${title('Materi belum ditemukan.','Pilih salah satu dari delapan topik Pedagogi Umum.')}<a class="btn" href="#pedagogi">Kembali ke Pedagogi Umum</a>`,'pedagogi');
  if(!topic)return shell(`${title('Pedagogi Umum, dari konsep ke keputusan.','Ringkasan lintas bidang studi, contoh kasus, dan latihan untuk memahami alasan di balik tindakan guru.')}<section class="card pu-intro"><div><span class="pill gold">RUANG BELAJAR PEDAGOGI UMUM</span><h2>Pelajari konsepnya.<br>Terapkan pada kasus kelas.</h2><p>Mulai dari delapan ringkasan di bawah, berlatih pada topik pilihan, lalu kerjakan tryout khusus Pedagogi Umum.</p><div class="pu-facts"><span>8 topik</span><span>${selectPedagogiQuestions(bank).length} soal orisinal</span><span>Belajar / Simulasi</span></div></div><div class="pu-tryout"><h3>Tryout khusus Pedagogi Umum</h3><p>30 soal acak dari ${selectPedagogiQuestions(bank).length} · ${pedagogiTryoutMinutes} menit latihan<br>PG, PG kompleks kategori, dan MCMA.</p>${btn('Mulai tryout PU','start-pu','primary','')}<p class="pu-duration">Durasi 55 menit adalah pengaturan latihan Nalar. Acuan ujian mengatur 150 menit untuk gabungan 50 PCK dan 30 PU.</p></div></section><section class="pu-section"><div class="section-heading"><div><h2>Pilih topik belajarmu</h2><p>Baca ringkasan, pelajari kasus, lalu terapkan lewat soal.</p></div></div><div class="pu-topic-grid">${pedagogiTopics.map(t=>`<article class="card pu-topic"><span class="icon-box">${icon(t.icon)}</span><h3><a href="#pedagogi/${t.id}">${esc(t.title)}</a></h3><p>${esc(t.intro)}</p><div class="pu-topic-meta">± ${t.minutes} menit baca · ${selectPedagogiQuestions(bank,t.id).length} soal</div><div class="pu-actions"><a class="btn" href="#pedagogi/${t.id}">Baca ringkasan</a>${btn('Latihan topik','practice-pu','ghost','',`data-topic="${t.id}"`)}</div></article>`).join('')}</div></section><section class="card pu-sources"><h2>Cara menggunakan materi ini</h2><p>Ringkasan dan contoh kasus disusun sebagai bahan belajar Nalar. Delapan topik merupakan pengelompokan belajar, bukan bobot bab resmi. Bank berisi ${selectPedagogiQuestions(bank).length} soal PU dengan pembahasan. Tryout memilih 30 soal acak dan mengutamakan soal yang belum muncul di riwayat browser. Soal yang sama dapat muncul kembali setelah beberapa sesi.</p><p>Mode Belajar membuka kunci setelah jawaban diperiksa dan mengunci respons. Mode Simulasi menampilkan pembahasan sesudah sesi selesai. Latihan per topik tanpa timer; tryout PU menggunakan timer 55 menit.</p><div class="ref-link">${sourceLinks(['R03','R08','R19'])}</div></section>`,'pedagogi');
  const position=pedagogiTopics.indexOf(topic),next=pedagogiTopics[position+1];
  return shell(`${title(esc(topic.title),`Ringkasan Pedagogi Umum · ± ${topic.minutes} menit baca · ${selectPedagogiQuestions(bank,topic.id).length} soal terkait`,`<a class="text-link" href="#pedagogi">Semua topik</a>`)}<div class="pu-reader"><article class="card pu-material"><p class="pu-lead">${esc(topic.intro)}</p><h2>Konsep inti</h2>${topic.concepts.map(([heading,body])=>`<section class="pu-concept"><h3>${esc(heading)}</h3><p>${esc(body)}</p></section>`).join('')}<section class="pu-case"><span class="pill gold">CONTOH KASUS LATIHAN</span><h2>Dari situasi ke keputusan</h2><h3>Situasi</h3><p>${esc(topic.example.problem)}</p><h3>Tindakan yang mendukung belajar</h3><p>${esc(topic.example.action)}</p><h3>Alasannya</h3><p>${esc(topic.example.reason)}</p></section><h2>Langkah mengambil keputusan</h2><ol>${topic.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><h2>Hal yang perlu dihindari</h2>${list(topic.pitfalls)}<section class="pu-recall"><h3>Cek pemahamanmu</h3><p>${esc(topic.recall)}</p><p>Coba jawab dengan contoh kelasmu sendiri sebelum memulai latihan.</p></section><h2>Rujukan belajar</h2><p class="pu-caption">Ringkasan dan kasus adalah penjelasan Nalar. Rujukan mendukung konsep dan kompetensi, bukan asal teks soal.</p><div class="ref-link">${sourceLinks(topic.sources)}</div></article><aside class="card pu-study"><span class="icon-box">${icon('book')}</span><h2>Siap menerapkan?</h2><p>Kerjakan ${selectPedagogiQuestions(bank,topic.id).length} soal pada topik ini tanpa batas waktu. Pilih Mode Belajar atau Mode Simulasi saat memulai.</p>${btn('Latihan topik ini','practice-pu','primary','',`data-topic="${topic.id}"`)}${btn('Tryout semua topik PU','start-pu','','')}<hr><h3>Topik berikutnya</h3><a href="${next?'#pedagogi/'+next.id:'#pedagogi'}">${next?esc(next.title):'Kembali ke peta materi'}</a></aside></div>`,'pedagogi');
}
